select jsonb_build_object(
 'enabled',(select enabled from spot_private.analytics_control),'test_only',(select test_only from spot_private.analytics_control),'dropped',(select dropped from spot_private.analytics_control),
 'analytics_rows',(select count(*)from spot_private.analytics_events),'active_day_rows',(select count(*)from spot_private.analytics_days),'fairness_rows',(select count(*)from spot_private.analytics_fairness),'anonymous_rollups',(select count(*)from spot_private.analytics_anonymous_rollups),'admission',(select count(*)from spot_private.analytics_admission),
 'fixture_auth',(select count(*)from auth.users where id::text like 'a1a15000-%'),'fixture_profiles',(select count(*)from profiles where id::text like 'a1a15000-%'),'fixture_storage',(select count(*)from storage.objects where name like 'a1a15000-%'),
 'unsafe_fixture_photo_receipts',(select count(*)from spot_private.photo_lifecycle_sets where user_id::text like 'a1a15000-%'and(state<>'purged'or writer<>'settled'or reserved_bytes<>0)),
 'fixture_photo_receipts',(select count(*)from spot_private.photo_lifecycle_sets where user_id::text like 'a1a15000-%'),
 'missing_current',(select count(*)from profiles p where not exists(select 1 from storage.objects o where o.bucket_id='profile-photos'and o.name=p.photo_path)),
 'discovery',(select discovery_enabled from spot_private.soma_v2_control),'cleanup',(select execute_enabled from spot_private.photo_cutover_control),'scheduler',(select scheduler_enabled from spot_private.photo_cutover_control),'jobs_paused',(select jobs_paused from spot_private.soma_v2_control),'retention_paused',(select paused from spot_private.retention_control),'notifications',(select enabled or delivery_enabled from spot_private.notification_control),
 'private_rls',(select bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='spot_private'and c.relname in('analytics_control','analytics_admission','analytics_events','analytics_days','analytics_fairness','analytics_anonymous_rollups')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'schema',n.nspname,'body_md5',md5(p.prosrc)))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('spot_private','public')and p.proname in('analytics_canonical','analytics_observe','analytics_emit','analytics_admitted','analytics_purge','analytics_summary'))
)state;
